const __quietstartKits = {
"rewardInstall": (// Business policy only. Every target, catalogue and new-app ticket is issued
// and revalidated by the host; this module cannot read a screen or execute input.
function createRewardInstallKit(options = {}) {
  const copy = value => JSON.parse(JSON.stringify(value));
  const clean = value => String(value ?? '').replace(/[\s\u200b\ufeff]/g, '');
  const token = value => typeof value === 'string' && value.length > 0 && value.length <= 240;
  function initial(now, binding = {}) {
    const config = { ...options, ...(binding.stage || {}) };
    config.taskActionText = binding.stage?.taskActionText ?? binding.stage?.actionText ?? config.taskActionText ?? config.actionText;
    config.taskOpenText = binding.stage?.taskOpenText ?? binding.stage?.openText ?? config.taskOpenText ?? config.openText;
    config.taskDoneText = binding.stage?.taskDoneText ?? binding.stage?.doneText ?? config.taskDoneText ?? config.doneText;
    const childMode = token(binding.rowRef) && typeof binding.name === 'string' && !!clean(binding.name);
    for (const key of ['dwellMs', 'maxTasks', 'maxRefreshes', 'targetBalance', 'pointsPerTask', 'scrollSpeed']) {
      if (config[key] !== undefined && (!Number.isSafeInteger(config[key]) || config[key] < (key === 'maxRefreshes' ? 0 : 1))) throw Error('invalid-install-config:' + key);
    }
    if (!childMode && !['targetBalance', 'pointsPerTask', 'maxTasks', 'maxRefreshes', 'dwellMs'].every(key => Number.isSafeInteger(config[key]))) throw Error('incomplete-install-config');
    config.dwellMs ??= 5000; config.cleanupInstalled ??= true; config.scrollSpeed ??= 800;
    return { config, childMode, phase: childMode ? (config.cleanupInstalled ? 'catalog-before' : 'row-tap') : 'balance',
      rowRef: binding.rowRef || '', name: clean(binding.name), actionSequence: binding.actionSequence || 0,
      ownerAbility: copy(binding.ownerAbility || options.ownerAbility || {
        moduleName: binding.returnModuleName || options.returnModuleName || '',
        abilityName: binding.returnAbilityName || options.returnAbilityName || '' }),
      stage: copy(binding.stage || null), nextReadAt: now, startedAt: now, lastObservedAt: now, phaseReads: 0,
      chooserEnabled: Array.isArray(binding.chooserTexts) && binding.chooserTexts.length > 0,
      chooserMaxReads: binding.chooserMaxReads || 9, chooserPollMs: binding.chooserPollMs || 250,
      confirmMaxReads: binding.confirmMaxReads || 16, confirmPollMs: binding.confirmPollMs || 500,
      chooserSelections: 0, chooserSeen: false,
      missingFrames: 0, absentFrames: 0, marketSeen: false, marketAction: '', catalogTicket: '', catalogCount: 0,
      newAppTicket: '', rewardConfirmed: false, done: false, paused: false, transportAvailable: true, note: '',
      completedTasks: 0, refreshes: 0, scrolls: 0, topScrolls: 0, balanceReads: 0, balance: -1, objectiveReached: false };
  }
  function valid(s, now) {
    if (!s || !s.config || !Number.isSafeInteger(now) || now < 0 ||
      !['balance', 'find', 'catalog-before', 'row-tap', 'market-wait', 'install-wait', 'market-close',
        'open-row-wait', 'catalog-open', 'catalog-delta', 'open-installed', 'chooser', 'dwell', 'launch-owner', 'verify-reward', 'cleanup', 'return-top', 'refresh'].includes(s.phase) ||
      ['actionSequence', 'nextReadAt', 'startedAt', 'phaseReads', 'missingFrames', 'absentFrames',
        'completedTasks', 'refreshes', 'scrolls', 'topScrolls', 'balanceReads', 'catalogCount', 'lastObservedAt',
        'chooserMaxReads', 'chooserPollMs', 'chooserSelections', 'confirmMaxReads', 'confirmPollMs'].some(key => !Number.isSafeInteger(s[key]) || s[key] < 0) ||
      s.phase === 'catalog-open' && (!Number.isSafeInteger(s.openRowReadAt) || s.openRowReadAt < s.nextReadAt) ||
      typeof s.name !== 'string' || s.name.length > 160 || typeof s.rowRef !== 'string' || s.rowRef.length > 240 ||
      ['done', 'paused', 'rewardConfirmed', 'childMode'].some(key => typeof s[key] !== 'boolean')) throw Error('invalid-install-checkpoint');
  }
  function output(s, outcome = 'waiting', intent, applied) {
    return { status: s.paused ? 'paused' : s.done ? 'complete' : 'running', outcome,
      checkpoint: s, message: s.note, ...(s.transportAvailable === false ? {transportAvailable:false} : {}), ...(intent ? { intent, applied } : {}) };
  }
  function attempt(s, kind, data, effect, delay = 0) {
    return output(s, 'waiting', { kind, ...data, rowRef: s.rowRef, name: s.name, sequence: s.actionSequence }, { effect, delay });
  }
  function tap(s, targetRef, effect, delay = 0) {
    if (!token(targetRef)) return fail(s, s.lastObservedAt, '声明的目标已失效');
    return attempt(s, 'tap', { targetRef }, effect, delay);
  }
  function fail(s, now, note) {
    s.note = note;
    if (s.childMode) s.done = true;
    else { s.phase = 'balance'; s.nextReadAt = now + 5000; s.balanceReads = 0; }
    return output(s, 'failed');
  }
  function waitForPage(s, now, note) { s.note = note; s.nextReadAt = now + 350; return output(s); }
  function pause(s, reason) { s.paused = true; s.note = reason; return output(s, 'waiting'); }
  function finish(s, now, note = '') {
    s.completedTasks++; s.refreshes = 0; s.scrolls = 0; s.topScrolls = 0;
    s.note = note || '安装任务奖励已确认';
