  }
  function rows(f) { return Array.isArray(f.rows) ? f.rows : Array.isArray(f.section?.rows) ? f.section.rows : []; }
  function action(value, wanted, config) {
    const word = wanted === 'install' ? config.taskActionText : wanted === 'open' ? config.taskOpenText : config.taskDoneText;
    return value === wanted || !!word && clean(value) === clean(word);
  }
  function row(s, f, wanted) {
    return rows(f).find(item => item && clean(item.name) === s.name &&
