      const item = row(s, f, 'install');
      const ref = item?.targetRef || f.rowTargetRef;
      if (!token(ref) && (f.rowsComplete === false || item)) {
        return waitForPage(s, now, '等待原安装任务的当前入口');
      }
      return tap(s, ref, 'market-start', 350);
    }
