        }
        if (s.childMode) {
          s.done = true;
          s.note = '安装页未打开，重新核对当前任务区';
          return output(s, 'rediscover-install-row');
        }
        s.phase = 'find';
        s.note = '原安装入口已变化，重新核对当前任务列表';
