        }
        else { s.missingFrames = 0; if (action(m.action, 'open', config)) s.phase = 'market-close'; }
      }
      if (s.phase === 'install-wait') {
        s.nextReadAt = now + 1000; return output(s);
      }
    }
    if (s.phase === 'market-close') {
      if (pageReady(f) && row(s, f, 'open')) s.phase = 'open-row-wait';
      else {
        if (!marketMatches(s, m) || m.windowValid === false) return waitForPage(s, now, '等待确认当前安装页窗口');
        if (!token(m.closeRef)) return waitForPage(s, now, m.closeAmbiguous ? '等待唯一的安装页关闭入口' : '等待安装页关闭入口');
