      const openRef = found?.targetRef || (pageReady(f) ? f.openRowRef : '');
      if (token(openRef)) {
        s.openTargetRef = openRef;
        s.phase = config.cleanupInstalled && s.catalogTicket && s.catalogCount > 0 ? 'catalog-delta' : 'open-installed';
      } else {
        s.nextReadAt = now + 350; return output(s);
      }
