      return attempt(s, 'catalog-delta', { catalogTicket: s.catalogTicket }, 'catalog-open');
    }
    if (s.phase === 'catalog-delta') {
      if (f.newAppTicket !== undefined) { s.newAppTicket = token(f.newAppTicket) ? f.newAppTicket : ''; s.phase = 'open-installed'; }
